#!/usr/bin/env node
/* =============================================================================
   tools/apply_land026.mjs — THE WHOLE CHAIN + THE RECORD (0.26)
   run:  node tools\\apply_land026.mjs            (install + verify)
         node tools\\apply_land026.mjs --gates    (install, then run the gate)
         node tools\\apply_land026.mjs --gates-only

   Carries its payload as base64 because .js does not land reliably on eyeZ.
   Every file is re-read from disk after writing and checked byte-for-byte and
   by sha256 against what was carried. Nothing is reported as installed unless
   it verified. A file that already matches is left alone and reported UNCHANGED.

   WHAT THIS CHANGES   -- supersedes apply_relay025, apply_bite026 and
     apply_scope026. Install this ONE and you are current and recorded.

     engine/zigcore.js       Relay 0.24 -> 0.25 (span bounds the BODY, not the hop;
                               snap blends toward density) and + ZigCore.Bite (life)
                               and ZigCore.Bounce (physics). Pure CPU, no WGSL, so
                               no Metal exposure. Timbre is untouched - it was
                               already there.
     test/vertebra_ref.mjs   rewritten for span.
     test/bite_ref.mjs       NEW. The gate becomes 44.
     tools/relay_scope.html  THE TWO NERVOUS SYSTEMS, wired. MIDI (the EWI) drives
                               what moves: a note reaches the body only if Bite lets
                               it, and every bite throws the ball. AUDIO (the loop
                               off the RC-600, via Timbre) drives the CONDITIONS:
                               ground light and warmth. Audio never touches geometry.
     species/sickleswarm.js  THE SPECIMEN, opt-in via ZIG_RELAY. The six MELODIC
                               STRATA bands ARE the six segments, so a wave crosses
                               the body as bands lighting in order up its vertical
                               axis - NO new shader path, NO new binding, and the
                               strata shader is already Metal-proven. Diffed line by
                               line: two lines moved into an else branch, everything
                               else is addition inside a RELAY_ON guard.
                               Turn it on with  sickleswarm.html#relay=1
                               NOT BOOT-GATED HERE - see below.
     tools/bite_replay.mjs   NEW - replay a .mid through the chain, headless:
                               node tools\bite_replay.mjs --train <file.mid>
   ========================================================================== */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";

/* FINDING THE ROOT IS NOT ASSUMED, IT IS PROVEN.
   Two ways to guess where the repo is, and neither is trusted on faith:
     1. fileURLToPath(import.meta.url)/..  — fileURLToPath, NOT url.pathname. On
        Windows the latter yields "/C:/Users/..." and joining it onto anything
        produces "C:\\C:\\Users\\..." — the fault that killed the first build of
        this installer. It passed on Linux and could not pass on eyeZ.
     2. process.cwd() — correct whenever you run it from the repo root.
   A candidate is only accepted if engine/zigcore.js and test/ are actually
   THERE. An installer that cannot prove where it is must not write. */
const CANDIDATES = [
  path.resolve(path.dirname(fileURLToPath(import.meta.url)), ".."),
  process.cwd()
];
const looksRight = (d) => existsSync(path.join(d, "engine", "zigcore.js")) &&
                          existsSync(path.join(d, "test")) &&
                          existsSync(path.join(d, "tools"));
const ROOT = CANDIDATES.find(looksRight);
if (!ROOT) {
  console.log("\n  CANNOT LOCATE THE REPO. Tried:");
  CANDIDATES.forEach((d) => console.log("    " + d));
  console.log("  Run this from C:\\Users\\billy\\Zigverse — nothing was written.\n");
  process.exit(1);
}
const args = process.argv.slice(2);
const gates = args.includes("--gates") || args.includes("--gates-only");
const only  = args.includes("--gates-only");
const sha = (b) => createHash("sha256").update(b).digest("hex").slice(0, 16);

const PAYLOAD = [
  { path: 'engine/zigcore.js', bytes: 199939, sha: 'd4c20de6f211c1e0', b64: "" },
  { path: 'species/sickleswarm.js', bytes: 118601, sha: 'a2e4692d19b2194e', b64: "" },
  { path: 'test/vertebra_ref.mjs', bytes: 18687, sha: '272cd15c69f34903', b64: "" },
  { path: 'test/bite_ref.mjs', bytes: 8972, sha: 'e0b875ad4c848341', b64: "" },
  { path: 'tools/relay_scope.html', bytes: 14639, sha: 'a53c7e0d33512192', b64: "" },
  { path: 'tools/bite_replay.mjs', bytes: 6801, sha: '9c8a448720bf6100', b64: "" },
];

let bad = 0;
if (!only) {
  console.log("\n  ZIGVERSE - installing THE WHOLE CHAIN (0.26)\n  root: " + ROOT + "\n");
  for (const p of PAYLOAD) {
    const dst = path.join(ROOT, p.path);
    const want = Buffer.from(p.b64, "base64");
    const had = existsSync(dst) ? readFileSync(dst) : null;
    if (had && had.equals(want)) {
      console.log("  UNCHANGED  " + p.path.padEnd(26) + p.bytes + " bytes");
      continue;
    }
    writeFileSync(dst, want);
    const back = readFileSync(dst);
    const okBytes = back.length === p.bytes, okSha = sha(back) === p.sha;
    if (okBytes && okSha) {
      console.log("  WROTE      " + p.path.padEnd(26) + p.bytes + " bytes · sha " + p.sha + " OK");
    } else {
      bad++;
      console.log("  MISMATCH   " + p.path.padEnd(26) + "wrote " + back.length + "/" + p.bytes +
                  " bytes · sha " + sha(back) + " vs " + p.sha);
    }
  }
  if (bad) {
    console.log("\n  " + bad + " FILE(S) DID NOT VERIFY — stop here and send this output to Glyph.");
    console.log("  Do not run the gate on a partial install.\n");
    process.exit(1);
  }
  console.log("\n  all files verified.\n");
}


/* ------------------------------------------------- THE RECORD (append only) */
{
  const LOG = path.join(ROOT, "briefs", "Session_Log.md");
  const ENTRY = Buffer.from("", "base64");
  const ANCHOR = Buffer.from("bmQKYHRvb2xzL2AgYXJlIGFjdHVhbGx5IHRoZXJlLCBhbmQgcmVmdXNpbmcgdG8gd3JpdGUgYXQgYWxsIG90aGVyd2lzZS4KCipUaGUgbWFjaGluZSB0aGF0IHRlc3RzIGlzIG5vdCB0aGUgbWFjaGluZSB0aGF0IHJ1bnMuKiBTYW1lIHNoYXBlIGFzIHRoZSBNZXRhbCBsZXNzb24uCg==", "base64");
  const WANT = "95101c64bb77a54a";
  const cur = readFileSync(LOG);
  if (cur.includes(ENTRY)) console.log("  UNCHANGED  briefs/Session_Log.md   entry already present");
  else if (!cur.subarray(-ANCHOR.length).equals(ANCHOR)) {
    console.log("  SKIPPED    briefs/Session_Log.md   does not end where expected -");
    console.log("             something was appended since. Files are installed; send this");
    console.log("             to Glyph and the entry will be rebuilt against the current file.");
  } else {
    const next = Buffer.concat([cur, ENTRY]);
    writeFileSync(LOG, next);
    const back = readFileSync(LOG);
    if (back.length === next.length && sha(back) === WANT)
      console.log("  APPENDED   briefs/Session_Log.md   " + cur.length + " -> " + back.length +
                  " bytes  (+" + ENTRY.length + ") . sha " + sha(back) + " OK");
    else { bad++; console.log("  MISMATCH   briefs/Session_Log.md"); }
  }
}

if (!gates) {
  console.log("  next:  node tools\\apply_land026.mjs --gates-only\n");
  process.exit(0);
}

/* ---------------------------------------------------------------- THE GATE */
console.log("  REFERENCE GATE\n");
let syn = 0;
for (const f of ["engine/zigcore.js", "engine/zigwebgpu.js", "engine/zigmesh.js", "engine/zigmidi.js"]) {
  try { execFileSync(process.execPath, ["--check", path.join(ROOT, f)]); }
  catch (e) { syn++; console.log("  node --check FAILED: " + f); }
}
console.log("  node --check  " + (syn ? syn + " FAILED" : "clean (4 files)"));

const dir = path.join(ROOT, "test");
const tests = readdirSync(dir).filter((f) => f.endsWith("_ref.mjs")).sort();
let pass = 0; const failed = [];
for (const t of tests) {
  try { execFileSync(process.execPath, [path.join(dir, t)], { stdio: "pipe" }); pass++; }
  catch (e) {
    failed.push(t);
    console.log("  FAIL  " + t);
    const out = ((e.stdout || "") + (e.stderr || "")).toString().trim().split("\n").slice(-4);
    out.forEach((l) => console.log("        " + l));
  }
}
console.log("\n  REFERENCE GATE: " + pass + "/" + tests.length + " PASS");
if (syn || failed.length) {
  console.log("  STOP — send this output to Glyph before landing anything.\n");
  process.exit(1);
}
console.log("  vertebra_ref is included and passing.\n");
console.log("  land it:      .\\LAND.cmd     (message: \"BITE + BOUNCE - the two nervous systems\")");
console.log("  then play:    node tools\\serve.mjs\n");
